{
  "$schema": "https://vega.github.io/schema/vega-lite/v5.json",
  "data": {
    "url": "/results.csv"
  },
  "transform": [
    {
      "calculate": "datum.home_score + datum.away_score",
      "as": "total_score"
    }
  ],
  "mark": "bar",
  "encoding": {
    "x": {
      "field": "total_score",
      "type": "quantitative",
      "bin": true,
      "title": "Total Goals (Home + Away)"
    },
    "y": {
      "aggregate": "count",
      "type": "quantitative",
      "title": "Number of Matches"
    }
  }
}

